package service

import (
	"fmt"
	"sync"

	"github.com/google/uuid"
)

// User represents a user in the system
type User struct {
	ID    string `json:"id"`
	Name  string `json:"name"`
	Email string `json:"email"`
}

var (
	users  = make(map[string]User)
	mutex  sync.RWMutex
	nextID = 1 // This will be removed once uuid is fully integrated
)

// CreateUser creates a new user and adds it to the system
func CreateUser(u User) User {
	mutex.Lock()
	defer mutex.Unlock()

	// Generate a new UUID for the user ID
	u.ID = uuid.New().String()
	users[u.ID] = u
	return u
}

// GetAllUsers returns a list of all users
func GetAllUsers() []User {
	mutex.RLock()
	defer mutex.RUnlock()

	var list []User
	for _, u := range users {
		list = append(list, u)
	}
	return list
}

// GetUserByID retrieves a user by their ID
func GetUserByID(id string) (User, bool) {
	mutex.RLock()
	defer mutex.RUnlock()

	u, ok := users[id]
	return u, ok
}

package api

import (
	"encoding/json"
	"net/http"

	"tenkai/experiments/runs/20251217-180005_context_abtest/alt1_standard_context/legacy_refactor/rep-8/internal/service"
)

// ListUsersHandler handles GET requests to list all users
func ListUsersHandler(w http.ResponseWriter, r *http.Request) {
	users := service.GetAllUsers()
	json.NewEncoder(w).Encode(users)
}

// CreateUserHandler handles POST requests to create a new user
func CreateUserHandler(w http.ResponseWriter, r *http.Request) {
	var u service.User
	if err := json.NewDecoder(r.Body).Decode(&u); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}

	newUser := service.CreateUser(u)
	w.WriteHeader(http.StatusCreated)
	json.NewEncoder(w).Encode(newUser)
}

// GetUserHandler handles GET requests for a specific user by ID
func GetUserHandler(w http.ResponseWriter, r *http.Request) {
	id := r.URL.Path[len("/users/"):]
	u, ok := service.GetUserByID(id)
	if !ok {
		http.NotFound(w, r)
		return
	}
	json.NewEncoder(w).Encode(u)
}

package main

import (
	"log"
	"net/http"

	"tenkai/experiments/runs/20251217-180005_context_abtest/alt1_standard_context/legacy_refactor/rep-8/internal/api"
)

func main() {
	http.HandleFunc("/users", func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet:
			api.ListUsersHandler(w, r)
		case http.MethodPost:
			api.CreateUserHandler(w, r)
		default:
			http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		}
	})

	http.HandleFunc("/users/", api.GetUserHandler)

	log.Println("Server starting on :8080...")
	if err := http.ListenAndServe(":8080", nil); err != nil {
		log.Fatal(err)
	}
}
